import{R as o,p as r,e as i,f as s,j as t,q as a,z as l,U as n}from"./chunks/framework.BKStFnx-.js";const g=JSON.parse('{"title":"Address","description":"","frontmatter":{},"headers":[],"relativePath":"browser/ui-reference/fields/address.md","filePath":"browser/ui-reference/fields/address.md","lastUpdated":1781175345000}'),c={name:"browser/ui-reference/fields/address.md"};function u(h,e,p,f,b,m){const d=r("FormiePreview");return i(),s("div",null,[e[0]||(e[0]=t("h1",{id:"address",tabindex:"-1"},[a("Address "),t("a",{class:"header-anchor",href:"#address","aria-label":'Permalink to "Address"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Address is the address field, made up of multiple child inputs with optional autocomplete and current-location features.",-1)),e[2]||(e[2]=t("p",null,"Use this page as the reference for the selectors and parts of the field that need to stay stable when you customize markup.",-1)),e[3]||(e[3]=t("h2",{id:"preview",tabindex:"-1"},[a("Preview "),t("a",{class:"header-anchor",href:"#preview","aria-label":'Permalink to "Preview"'},"​")],-1)),l(d,{src:"../examples/address.preview.ts"}),e[4]||(e[4]=n('<h2 id="field-structure" tabindex="-1">Field structure <a class="header-anchor" href="#field-structure" aria-label="Permalink to &quot;Field structure&quot;">​</a></h2><p>In the default output, Address behaves like a parent field that owns a group of child fields:</p><ul><li>the parent field wraps grouped sub-field rows</li><li>each child input is still rendered as a normal field input</li><li>provider modules target the autocomplete child and populate related sub-fields</li></ul><h2 id="browser-selectors" tabindex="-1">Browser selectors <a class="header-anchor" href="#browser-selectors" aria-label="Permalink to &quot;Browser selectors&quot;">​</a></h2><p>Address provider modules resolve sub-field inputs with <code>findAddressFieldInput()</code> and <code>ADDRESS_SELECTORS</code>. All address-owned hooks use the <code>data-formie-address-*</code> namespace:</p><table tabindex="0"><thead><tr><th>Selector</th><th>Purpose</th></tr></thead><tbody><tr><td><code>[data-formie-address-autocomplete-input]</code></td><td>Provider-owned autocomplete input</td></tr><tr><td><code>[data-formie-address-line1-input]</code></td><td>Address line 1</td></tr><tr><td><code>[data-formie-address-line2-input]</code></td><td>Address line 2</td></tr><tr><td><code>[data-formie-address-line3-input]</code></td><td>Address line 3</td></tr><tr><td><code>[data-formie-address-city-input]</code></td><td>City</td></tr><tr><td><code>[data-formie-address-state-input]</code></td><td>State / region (visible control)</td></tr><tr><td><code>[data-formie-address-state-dynamic]</code></td><td>State / region control when using <strong>Dropdown when available</strong></td></tr><tr><td><code>[data-formie-address-state-autofill-anchor]</code></td><td>Persistent password-manager/browser autofill target (<code>autocomplete=&quot;address-level1&quot;</code>)</td></tr><tr><td><code>[data-formie-address-zip-input]</code></td><td>Postal code</td></tr><tr><td><code>[data-formie-address-country-input]</code></td><td>Country</td></tr><tr><td><code>[data-formie-address-location]</code></td><td>Current-location trigger</td></tr></tbody></table><p>Preserve these selectors if you override the field template.</p><p>Older forms may still render legacy bare hooks such as <code>[data-address1]</code> or <code>[data-state]</code>. Provider modules fall back to those automatically via <code>ADDRESS_LEGACY_SELECTORS</code>.</p><h2 id="built-in-provider-behavior" tabindex="-1">Built-in provider behavior <a class="header-anchor" href="#built-in-provider-behavior" aria-label="Permalink to &quot;Built-in provider behavior&quot;">​</a></h2><p>Current built-in address providers include:</p><ul><li><code>address-finder</code></li><li><code>google-address</code></li><li><code>loqate</code></li><li><code>place-kit</code></li></ul><p>Address providers mount against the target field, defer setup until the field becomes visible, and can re-check visibility after page navigation or submit results.</p><h2 id="address-events" tabindex="-1">Address events <a class="header-anchor" href="#address-events" aria-label="Permalink to &quot;Address events&quot;">​</a></h2><p>Provider-specific populate and lifecycle events are documented on <a href="/formie/browser/behavior/javascript-events">JavaScript events</a>, for example:</p><ul><li><code>formie:address:place-kit:before-init</code></li><li><code>formie:address:place-kit:populate</code></li><li><code>formie:address:address-finder:populate</code></li><li><code>formie:address:google:populate</code></li></ul><h2 id="state-province-loading" tabindex="-1">State / province loading <a class="header-anchor" href="#state-province-loading" aria-label="Permalink to &quot;State / province loading&quot;">​</a></h2><p>When the State / Province sub-field uses <strong>Dropdown when available</strong>, picking a country fetches subdivision metadata. While that request is in flight:</p><ul><li>the address root is marked with <code>[data-formie-address-state-fetching]</code> and the country control shows a spinner</li><li>the state column shows a skeleton placeholder via <code>[data-formie-address-state-skeleton-active]</code> so layout does not jump</li><li>cached country lookups skip the loading UI on repeat selections</li></ul><h2 id="state-province-autofill" tabindex="-1">State / province autofill <a class="header-anchor" href="#state-province-autofill" aria-label="Permalink to &quot;State / province autofill&quot;">​</a></h2><p>Password managers and browser autofill target a persistent anchor input:</p><ul><li><code>[data-formie-address-state-autofill-anchor]</code> with <code>autocomplete=&quot;address-level1&quot;</code></li><li>the visible state control uses <code>autocomplete=&quot;off&quot;</code> so managers do not race a lazy-loaded input</li></ul><p>After subdivisions load, the module reconciles the anchor value onto the visible text input, select, or combobox. Mount sweeps and <code>-webkit-autofill</code> animation hooks catch late autofill batches.</p><p>Custom Address templates do not need to render the autofill anchor manually. The <code>address-state</code> module injects it at runtime when <strong>Dropdown when available</strong> is enabled.</p><h2 id="styling-classes" tabindex="-1">Styling classes <a class="header-anchor" href="#styling-classes" aria-label="Permalink to &quot;Styling classes&quot;">​</a></h2><p>These classes are for presentation only. They are not behavior requirements:</p><h3 id="field-input" tabindex="-1">Field input <a class="header-anchor" href="#field-input" aria-label="Permalink to &quot;Field input&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>formie-input</code></td><td>Shared address input styling and focus treatment</td></tr><tr><td><code>formie-field-nested</code></td><td>Nested address subfield styling class</td></tr></tbody></table><h3 id="sub-field-rows" tabindex="-1">Sub-field rows <a class="header-anchor" href="#sub-field-rows" aria-label="Permalink to &quot;Sub-field rows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>formie-subfield-rows</code></td><td>Address subfield rows wrapper</td></tr><tr><td><code>formie-subfield-row</code></td><td>Individual address subfield row</td></tr></tbody></table><h3 id="autocomplete" tabindex="-1">Autocomplete <a class="header-anchor" href="#autocomplete" aria-label="Permalink to &quot;Autocomplete&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>formie-autocomplete-wrapper</code></td><td>Address autocomplete wrapper styling class</td></tr><tr><td><code>formie-autocomplete-placeholder</code></td><td>Address autocomplete placeholder styling class</td></tr></tbody></table><h3 id="location-trigger" tabindex="-1">Location trigger <a class="header-anchor" href="#location-trigger" aria-label="Permalink to &quot;Location trigger&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>formie-address-location</code></td><td>Current-location trigger styling class</td></tr></tbody></table><h3 id="state-province-loading-1" tabindex="-1">State / province loading <a class="header-anchor" href="#state-province-loading-1" aria-label="Permalink to &quot;State / province loading&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class / attribute</th><th>Description</th></tr></thead><tbody><tr><td><code>formie-address-state-skeleton</code></td><td>Skeleton placeholder wrapper shown while subdivisions load</td></tr><tr><td><code>formie-address-state-skeleton-input</code></td><td>Skeleton input bar</td></tr><tr><td><code>[data-formie-address-state-fetching]</code></td><td>Set on the address root while subdivision data is loading</td></tr><tr><td><code>[data-formie-address-state-skeleton-active]</code></td><td>Set on the state field while the skeleton is visible</td></tr></tbody></table><h2 id="validation-notes" tabindex="-1">Validation notes <a class="header-anchor" href="#validation-notes" aria-label="Permalink to &quot;Validation notes&quot;">​</a></h2><ul><li>Child inputs still validate as normal Formie inputs.</li><li>Required and error handling should stay aligned across parent and child output.</li><li>Heavy markup changes should be tested with real provider population flows.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/formie/browser/ui-reference/fields/">Fields</a></li><li><a href="/formie/browser/behavior/javascript-events">JavaScript events</a></li><li><a href="/formie/browser/behavior/manual-initialization">Manual initialization</a></li></ul>',39))])}const w=o(c,[["render",u]]);export{g as __pageData,w as default};
